import spidev

def read_mcp3208(spi, channel):
    if not 0 <= channel <= 7:
        raise ValueError("Channel must be between 0 and 7")
    cmd = [0b00000110 | (channel << 2), (channel & 0x03) << 6, 0x00]
    try:
        resp = spi.xfer2(cmd)
        val = ((resp[1] & 0x0F) << 8) | resp[2]
        return val
    except Exception as e:
        raise RuntimeError(f"SPI transfer failed: {e}")

if __name__ == "__main__":
    spi = spidev.SpiDev()
    spi.open(0, 0)  # Bus 0, Chip Select 0
    spi.max_speed_hz = 1_000_000
    spi.mode = 0
    try:
        adc_value = read_mcp3208(spi, 3)
        print(f"Raw ADC value: {adc_value}")
    except Exception as e:
        print(f"Error reading ADC: {e}")
    finally:
        spi.close()

