        else:
            self._run_tpu_inference(image)

    def _run_inference(self, interpreter: tflite.Interpreter, image: np.ndarray, config: configargparse.Namespace):
        input_details = interpreter.get_input_details()
        if input_details[0]["shape"][1] != image.shape[1]:
            img = cv2.resize(image, (input_details[0]["shape"][1], input_details[0]["shape"][2]))
        else:
            img = image
        input_data = np.expand_dims(img, axis=0).astype(input_details[0]["dtype"])
        interpreter.set_tensor(input_details[0]["index"], input_data)
        interpreter.invoke()
        output_data = interpreter.get_tensor(input_details[0]["index"])
        self._post_detection(output_data[0], input_details[0]["shape"][1], input_details[0]["shape"][2], interpreter)

    def _run_tpu_inference(self, image: np.ndarray):
        self.notify("Running on Edge TPU", severity="warning")
        # The TPU delegate handles the inference.  This is a placeholder.
        pass

    def _post_detection(self, detection_result: np.ndarray, image_height: int, image_width: int, model_metadata: Tuple[int, int], scale_factor: float = 1.0):
        try:
            boxes = detection_result
            classes = model_metadata[0]
            scores = detection_result[1]
            self._filter_detections(boxes, classes, scores, image_height, image_width, self.config)
        except Exception as e:
            logger.error("Error after post detection: %s", e, exc_info=True)

    def _filter_detections(self, boxes: np.ndarray, classes: List[int], scores: np.ndarray, image_height: int, image_width: int, config: configargparse.Namespace):
        mask = scores > config.score_threshold
        boxes = boxes[mask]
        classes = [classes[i] for i in range(len(mask))[mask]]
        scores = scores[mask]
        if len(boxes) > 0:
            self.notify("Detected {0} object(s) with score {1}".format(
                len(boxes), np.max(scores)))
            self._draw_bounding_boxes(image_width, image_height, boxes, classes, scores, self.config)
        else:
            self._end_recording()

    def _draw_bounding_boxes(self, image_width: int, image_height: int, boxes: np.ndarray, classes: List[int], scores: np.ndarray, config: configargparse.Namespace):
        try:
            for i, box in enumerate(boxes):
                self._draw_rectangle(image_width, image_height, box, classes[i], scores[i])
        except Exception as e:
            logger.error("Error drawing bounding boxes: %s", e, exc_info=True)

    def _draw_rectangle(self, image_width: int, image_height: int, box: np.ndarray, class_id: int, score: float):
        start_point = tuple(int(b) for b in box)
        rectangle = cv2.rectangle(
            self.low_resolution,
            start_point,
            self._calculate_rectangle_coordinates(image_width, image_height, box),
            config.color,
            2,
        )
        text = "{0}: {1:.2f}".format(
            self._get_class_name(class_id),
            score,
        )
        cv2.putText(
            self.low_resolution,
            text,
            (start_point[0], start_point[1] - 10),
            cv2.FONT_HERSHEY_SIMPLEX,
            0.5,
            config.color,
            2,
            cv2.LINE_AA,
        )
        self.low_resolution_data.append(rectangle.data)

    def _calculate_rectangle_coordinates(self, image_width: int, image_height: int, box: np.ndarray) -> Tuple[int, int, int, int]:
        center_x = (box[0] + box[2]) / 2.0
        center_y = (box[1] + box[3]) / 2.0
        start_x = int(center_x - (box[2] - box[0]) / 2.0)
        start_y = int(center_y - (box[3] - box[1]) / 2.0)
        return (start_x, start_y), (start_x + (box[2] - box[0]), start_y + (box[3] - box[1]))

    def _get_class_name(self, class_id: int) -> str:
        return self.class_names[class_id]

    def _calculate_resolution_scale(self) -> Tuple[Tuple[Real, Real], Tuple[Real, Real]]:
        return (
            (self.config.resolution_width  / self.low_resolution[0],
              self.config.resolution_height / self.low_resolution[1]),
            (self.config.resolution_width  / self.low_resolution[0],
              self.config.resolution_height / self.low_resolution[1]),
        )

    def _handle_gps_data(self, image: np.ndarray):
        if self.config.gps_data_filter == "all":
            self.notify("GPS data available", severity="warning")
        else:
            self.notify("GPS data not available", severity="warning")

    def _end_recording(self):
        if time.time() - self.start_time >= MINIMUM_RECORDING_TIME:
            self.notify("Minimum recording time reached", severity="warning")
            self.stop()

    def start(self):
        self.start_time = time.time()

    def stop(self):
        self.picam2.stop()
        self.notify("Stopped", severity="info")


class ConfigManager:
    def __init__(self, config_file: str = None):
        self.config = self._parse_config(config_file)

    def _parse_config(self, config_file: str = None):
        parser = configargparse.ArgumentParser(
            default_config_files=DEFAULT_CONFIG_FILES if config_file is None else [config_file],
            auto_env_var_prefix="DETECTIONATOR_",
        )
        parser.add_argument("-c", "--config", is_config_file=True, help="Path to config file")
        parser.add_argument("--resolution-width", type=int, help="Camera resolution width")
        parser.add_argument("--resolution-height", type=int, help="Camera resolution height")
        parser.add_argument("--frame-rate", type=int, default=30, help="Camera frame rate")
        parser.add_argument("--inference-type", type=str, default="cpu", choices=["cpu", "edge_tpu"], help="Inference type")
        parser.add_argument("--model-path", type=str, help="Path to the TensorFlow Lite model")
        parser.add_argument("--num-threads", type=int, default=4, help="Number of threads for the TensorFlow Lite interpreter")
        parser.add_argument("--score-threshold", type=float, default=0.5, help="Minimum score for object detection")
        parser.add_argument("--color", type=str, default="0,255,0", help="Color of the bounding boxes (RGB)")
        parser.add_argument("--font", type=str, default="Arial", help="Font for the bounding boxes")
        parser.add_argument("--font-size", type=int, default=1, help="Font size for the bounding boxes")
        parser.add_argument("--rotation", type=int, default=0, help="Camera rotation")
        parser.add_argument("--exposure-mode", type=str, default="auto", help="Exposure mode")
        parser.add_argument("--awb-mode", type=str, default="auto", help="AWB mode")
        parser.add_argument("--zoom", type=float, default=1.0, help="Zoom")
        parser.add_argument("--sensor-absense", action="store_true", help="Forced sensor absence during warm-up")
        parser.add_argument("--gps", action="store_true", help="Enable GPS data")
        parser.add_argument("--gps-data-filter", type=str, default="none", choices=["none", "running", "all"], help="GPS data filtering")
        parser.add_argument("--low-resolution-scale", type=int, default=8, help="Low resolution scale")
        parser.add_argument("--output-file", type=str, help="Output file name")
        parser.add_argument("--record-length", type=int, default=10, help="Recording length (seconds)")
        parser.add_argument("--num-frames", type=int, help="Number of frames to keep in memory")
        return parser.parse_args()

    def camera_config(self) -> configargparse.Namespace:
        return self.args

    def model_config(self) -> configargparse.Namespace:
        return self.args

    def gps_config(self) -> configargparse.Namespace:
        return self.args

    def low_resolution_config(self) -> configargparse.Namespace:
        return self.args

    def notify(self, message: str, severity: str = "info", end_line: bool = True):
        if end_line:
            logger.info("-" * 80)
            logger.info(severity + " " + message)
            logger.info("-" * 80)
        else:
            logger.info(severity + " " + message)


def _scale_coord(x: Real, y: Real, resolution_scale: Tuple[Real, Real], low_resolution: Tuple[Real, Real]) -> Tuple[Real, Real]:
    scale_x, scale_y = resolution_scale
    return (x * scale_x + low_resolution[0]) / scale_y * scale_y + low_resolution[1], (y * scale_y + low_resolution[1]) / scale_x * scale_x + low_resolution[0]


def _clamp_coord(x: Real, y: Real, low_resolution: Tuple[Real, Real]) -> Tuple[Real, Real]:
    return max(0, min(x, low_resolution[0])), max(0, min(y, low_resolution[1]))


def _rectangle_coordinates(x1: Real, y1: Real, x2: Real, y2: Real, resolution_scale: Tuple[Real, Real], low_resolution: Tuple[Real, Real]) -> Tuple[Real, Real, Real, Real]:
    scale_x, scale_y = resolution_scale
    return (x1 * scale_x + low_resolution[0]) / scale_y, (y1 * scale_y + low_resolution[1]) / scale_x, (x2 * scale_x + low_resolution[0]) / scale_y, (y2 * scale_y + low_resolution[1]) / scale_x


def _draw_rectangle(image: np.ndarray, x1: Real, y1: Real, x2: Real, y2: Real, color: Tuple[int, int, int], font: str, font_size: int) -> None:
    cv2.rectangle(image, (int(x1), int(y1)), (int(x2), int(y2)), color, 2)
    cv2.putText(image, "{0} {1:.2f}".format(
        _get_class_name(int((x2 - x1) / 2.0)), (y2 - y1 - 10),
        cv2.FONT_HERSHEY_SIMPLEX,
        font_size,
        color,
        1,
        cv2.LINE_AA,
    )


def _get_class_name(index: int) -> str:
    return "unknown" if index < 0 or index >= len(self.class_names) else self.class_names[index]


def _yminnhm_scale_coordinates(ymin: Real, ymax: Real, resolution_scale: Tuple[Real, Real]) -> Tuple[Real, Real]:
    scale_x, scale_y = resolution_scale
    return (min(ymin, ymax) * scale_x) / scale_y, (max(ymin, ymax) * scale_x) / scale_y


def _rectangles_are_overlaps(r1: Tuple[Real, Real, Real, Real], r2: Tuple[Real, Real, Real, Real]) -> bool:
    x1, y1, x2, y2 = r1
    rx1, ry1, rx2, ry2 = r2
    return (x1 <= rx2 and x2 <= rx1 and y1 <= ry2 and y2 <= ry1)


def _detections_are_overlaps(d1: List[Tuple[Real, Real, Real, Real, float]], d2: List[Tuple[Real, Real, Real, Real, float]]) -> bool:
    if len(d1) == 0 or len(d2) == 0:
        return False
    b1 = _rectangles_are_overlaps(tuple(_rectangle_coordinates(x1, y1, x2, y2, resolution_scale, low_resolution))
                                    for x1, y1, x2, y2, _ in d1),
        b2 = _rectangles_are_overlaps(tuple(_rectangle_coordinates(x1, y1, x2, y2, resolution_scale, low_resolution))
                                      for x1, y1, x2, y2, _ in d2)
    return b1 and b2


def _rectangle_coordinates(x1: Real, y1: Real, x2: Real, y2: Real, resolution_scale: Tuple[Real, Real], low_resolution: Tuple[Real, Real]) -> Tuple[Real, Real, Real, Real]:
    return _clamp_coord(x1, y1, low_resolution), _clamp_coord(x2, y2, low_resolution)


def _rectangle_intersection(x1: Real, y1: Real, x2: Real, y2: Real, x3: Real, y3: Real, x4: Real, y4: Real) -> Tuple[Real, Real, Real, Real]:
    if (x1 >= x3 and x2 >= x4 and y1 >= y3 and y2 >= y4):
        return max(x1, x3), max(y1, y3), min(x2, x4), min(y2, y4)
    return None


def _intersection_area(i1: Tuple[Real, Real, Real, Real], i2: Tuple[Real, Real, Real, Real]) -> Tuple[Real, Real, Real, Real]:
    if i1 is None:
        return i2
    if i2 is None:
        return i1
    x1, y1, x2, y2 = i1
    x3, y3, x4, y4 = i2
    intersection = _rectangle_intersection(x1, y1, x2, y2, x3, y3, x4, y4)
    if intersection is None:
        return None, None, None, None
    return intersection


def _scale_detections(d: List[Tuple[Real, Real, Real, Real, float]], resolution_scale: Tuple[Real, Real]) -> List[Tuple[Real, Real, Real, Real, float]]:
    scale_x, scale_y = resolution_scale
    return (
        (x * scale_x + low_resolution[0]) / scale_y,
        (y * scale_y + low_resolution[1]) / scale_x,
        (x * scale_x + low_resolution[0]) / scale_y,
        (y * scale_y + low_resolution[1]) / scale_x,
        d[4],
    ) for x, y, _, _ in d)


def _clamp_detections(d: List[Tuple[Real, Real, Real, Real, float]]) -> List[Tuple[Real, Real, Real, Real, float]]:
    return tuple(
        (max(0, min(x, low_resolution[0])) / scale_y,
          max(0, min(y, low_resolution[1])) / scale_x,
          max(0, min(x, low_resolution[0])) / scale_y,
          max(0, min(y, low_resolution[1])) / scale_x,
          d[4]) for x, y, _, _ in d)


def _scale_bounding_boxes(boxes: np.ndarray, resolution_scale: Tuple[Real, Real]) -> np.ndarray:
    scale_x, scale_y = resolution_scale
    return (boxes[:, 0] * scale_x + low_resolution[0]) / scale_y, (boxes[:, 1] * scale_y + low_resolution[1]) / scale_x


def _clamp_bounding_boxes(boxes: np.ndarray) -> np.ndarray:
    return np.clip(boxes, 0, 1)


def _rectangle_coordinates(x1: Real, y1: Real, x2: Real, y2: Real, resolution_scale: Tuple[Real, Real], low_resolution: Tuple[Real, Real]) -> Tuple[Real, Real, Real, Real]:
    return _clamp_coord(x1, y1, low_resolution), _clamp_coord(x2, y2, low_resolution)


def _draw_bounding_boxes(image: np.ndarray, boxes: np.ndarray, color: Tuple[int, int, int], font: str, font_size: int) -> None:
    for box in boxes:
        x1, y1, x2, y2 = box
        _draw_rectangle(image, x1, y1, x2, y2, color, font, font_size)


def main() -> None:
    logging.basicConfig(level=logging.INFO)
    manager = ConfigManager()
    detectionator = Detectionator(manager.config_file)
    frames = 0
    consecutive_no_detection = 0
    start_time = time.time()
    notifier = sdnotify.SystemdNotifier()
    notifier.notify("started=1.0.0")
    try:
        while True:
            try:
                frames += 1
                if frames >= detectionator.num_frames:
                    frames -= detectionator.num_frames
                    start_time = time.time()
                    consecutive_no_detection = 0
                image = detectionator.picam2.capture_array("main")
                detectionator._detect_object(image)
                if detectionator.low_resolution_data:
                    for data in detectionator.low_resolution_data:
                        image[0, :, :, :] = data
                if not notifier.wait(timeout=1.0):
                    continue
                if time.time() - start_time >= detectionator.record_length:
                    consecutive_no_detection = 0
                    detectionator.start()
                else:
                    consecutive_no_detection += 1
                    if consecutive_no_detection >= CONSECUTIVE_NO_DETECTION:
                        detectionator._end_recording()
                if notifier.wait(timeout=1.0):
                    raise RuntimeError("Notification loop busy")
            except RuntimeError as e:
                logger.error("Notification loop busy: %s", e, exc_info=True)
            except Exception as e:
                logger.error("Error processing frame: %s", e, exc_info=True)
                detectionator._end_recording()
                break
    except KeyboardInterrupt:
        logger.info("Interrupted by user")
    finally:
        detectionator.stop()
        logger.info("Stopped detectionator")


if __name__ == "__main__":
    main()

