import cv2
import time
from picamera2 import Picamera2, PreviewConfiguration
from typing import Tuple, Optional

def configure_camera(resolution: Tuple[int, int] = (640, 360), framerate: int = 30) -> Picamera2:
    """Configures the PiCamera2 with specified resolution and framerate."""
    try:
        cam = Picamera2()
        config = PreviewConfiguration(main={"size": resolution, "format": "RGB888"}, controls={"FrameRate": framerate})
        cam.configure(config)
        return cam
    except Exception as e:
        raise RuntimeError(f"Camera configuration failed: {e}")


def display_frames(frame, window_name: str = "Camera Feed") -> None:
    """Displays a frame in a window with optional FPS overlay."""
    cv2.imshow(window_name, frame)
    key = cv2.waitKey(1) & 0xFF
    return key == 27 or key == ord('q')


def convert_to_grayscale(frame) -> cv2.Mat:
    """Converts a BGR frame to grayscale using OpenCV."""
    return cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)


def process_frame(frame, gray_frame) -> Tuple[cv2.Mat, float]:
    """Processes a frame, converting it to grayscale and estimating FPS."""
    gray_frame = convert_to_grayscale(frame)
    fps = 1.0 / (time.time() - start_time) if time.time() - start_time >= 1 else 0.0
    return gray_frame, fps


def main_loop(resolution: Tuple[int, int] = (640, 360), framerate: int = 30) -> None:
    """Main loop for capturing and displaying camera frames."""
    start_time = time.time()
    cam = None
    try:
        cam = configure_camera(resolution, framerate)
        cam.start()
        window_name = "Camera Feed"
        cv2.namedWindow(window_name, cv2.WINDOW_AUTOSIZE)
        while True:
            if not display_frames(cam.capture_array(), window_name):
                break
            frame = cam.capture_array()
            gray_frame, fps = process_frame(frame.copy(), None)  # Process a copy to avoid modifying original
            cv2.putText(frame, str(round(fps, 2)), (30, 60), cv2.FONT_HERSHEY_SIMPLEX, 1.0, (0, 0, 255), 2)
            cv2.imshow(window_name, frame)
    except Exception as e:
        print(f"Error during capture: {e}")
    finally:
        if cam is not None:
            cam.stop()
        cv2.destroyAllWindows()


if __name__ == "__main__":
    main_loop()

