import cv2
import numpy as np
import RPi.GPIO as GPIO
from picamera2 import Picamera2
import time
import os
import signal
import sys

# Configuration (replace with your actual values)
CONFIG = {
    "POSITIVE_LABEL": 1,
    "NEGATIVE_LABEL": 0,
    "POSITIVE_THRESHOLD": 1500,
    "TRAINING_FILE": "face_trainer/training.txt",  # Path to your training data
    "BOX_LOCK_PIN": 17,  # GPIO pin for the box lock
    "BOX_BUTTON_PIN": 27, # GPIO pin for the box button
    "CAMERA_WIDTH": 640, "CAMERA_HEIGHT": 480, # Camera resolution
    "FACE_DETECTION_CASCADE_PATH": "haarcascade_frontalface_default.xml" # Path to your Haar cascade file
}

class Hardware:
    def __init__(self):
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(CONFIG["BOX_LOCK_PIN"], GPIO.OUT)
        GPIO.setup(CONFIG["BOX_BUTTON_PIN"], GPIO.IN, pull_up_down=GPIO.PUD_UP) # Enable pull-up resistor
        self.box_is_locked = True  # Initialize box state

    def lock(self):
        GPIO.output(CONFIG["BOX_LOCK_PIN"], GPIO.HIGH)
        self.box_is_locked = True
        print("Box is now locked.")

    def unlock(self):
        GPIO.output(CONFIG["BOX_LOCK_PIN"], GPIO.LOW)
        self.box_is_locked = False
        print("Box is now unlocked.")

    def is_locked(self):
        return self.box_is_locked

    def is_button_up(self):
        return GPIO.input(CONFIG["BOX_BUTTON_PIN"]) == GPIO.HIGH

class FaceRecognizer:
    def __init__(self, training_file):
        try:
            self.face_recognizer = cv2.face.EigenFaceRecognizer_create()
            self.face_recognizer.read(training_file)
            print("Face recognizer loaded successfully.")
        except Exception as e:
            print(f"Error loading face recognizer: {e}")
            sys.exit(1) # Exit if face recognizer loading fails

    def recognize_face(self, gray_frame):
        try:
            id, confidence = self.face_recognizer.predict(gray_frame)
            return id, confidence
        except Exception as e:
            print(f"Error during face recognition: {e}")
            return None, None

class Camera:
    def __init__(self, width, height):
        self.picam2 = Picamera2()
        config = self.picam2.create_preview_configuration(main={"format": 'XRGB8888', "size": (width, height)})
        self.picam2.configure(config)
        self.picam2.start()
        time.sleep(1) # Allow camera to warm up

    def capture_frame(self):
        return self.picam2.capture_array()

    def close(self):
        self.picam2.close()

def main():
    signal.signal(signal.SIGINT, lambda *args: sys.exit(0)) # Graceful exit on Ctrl+C

    hardware = Hardware()
    if hardware.is_button_up():
        hardware.unlock()
        time.sleep(2) # Debounce delay
    else:
        print("Button not pressed, keeping locked.")
        hardware.lock()

    face_recognizer = FaceRecognizer(CONFIG["TRAINING_FILE"])
    camera = Camera(CONFIG["CAMERA_WIDTH"], CONFIG["CAMERA_HEIGHT"])

    try:
        while True:
            if hardware.is_button_up() or (hardware.is_locked and not hardware.is_button_up()):
                if hardware.is_locked:
                    print("Button pressed, looking for face...")
                    gray_frame = cv2.cvtColor(camera.capture_frame(), cv2.COLOR_BGR2GRAY)
                    id, confidence = face_recognizer.recognize_face(gray_frame)

                    if id is None or confidence <= CONFIG["POSITIVE_THRESHOLD"]:
                        print("Unknown face detected. Keeping box locked.")
                    else:
                        print(f"Recognized face! ID: {id}, Confidence: {confidence}")
                        hardware.unlock()
                        time.sleep(5) # Keep unlocked for 5 seconds
                        hardware.lock()
            time.sleep(0.1) # Reduce CPU usage

    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        camera.close()
        print("Exiting...")

if __name__ == "__main__":
    main()

