import smbus2
import time
import datetime
import logging
import threading
import queue
import json
import numpy as np
import matplotlib.pyplot as plt
import picamera2
import signal
import sys
import os

# Constants and Configuration
DEFAULT_CONFIG = {
    'sampling_rate': 5,
    'motion_detection_threshold': 1.0,
    'enable_camera': False,
    'log_max_size': 1048576,  # 1MB
    'logging_file_path': 'beehive.log'
}

# Global Variables
config = DEFAULT_CONFIG.copy()  # Initialize config with defaults
running = True
frame_buffer = None
frame_buffer_lock = threading.Lock()
camera = None
log_file = None
frame_queue = queue.Queue(maxsize=300) # Queue for storing thermal frames

# Custom Exception Classes
class ConfigurationError(Exception):
    pass

class SensorError(Exception):
    pass

# Configuration Management Functions
def load_config(config_file="config.json"):
    global config
    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
        # Validate config values
        if not all(isinstance(v, (int, float)) for v in config.values()):
            raise ConfigurationError("Invalid configuration values")
        if not 1 <= config['sampling_rate'] <= 10:
            config['sampling_rate'] = 5  # Default value
        if not 0.0 <= config['motion_detection_threshold'] <= 5.0:
            config['motion_detection_threshold'] = 1.0  # Default value
        if config['enable_camera'] not in (True, False):
            config['enable_camera'] = False  # Default value
        if not 1024 <= config['log_max_size'] <= 1048576:
            config['log_max_size'] = 1048576  # Default value
        if not config['logging_file_path'].endswith('.log'):
            config['logging_file_path'] = config['logging_file_path'] + '.log'
        logging.info("Configuration loaded from %s", config_file)
    except FileNotFoundError:
        logging.warning("Configuration file not found, using default configuration.")
    except json.JSONDecodeError:
        logging.error("Invalid JSON in configuration file, using default configuration.")
    except ConfigurationError as e:
        logging.error("Configuration error: %s, using default configuration.", e)
    except Exception as e:
        logging.error("Unexpected error loading configuration: %s, using default configuration.", e)

# Logging Configuration
def setup_logging(log_file_path):
    global log_file
    log_file = None
    try:
        log_file = open(log_file_path, 'a')
        logging.basicConfig(
            level=logging.INFO,
            format='%(asctime)s - %(levelname)s - %(message)s',
            handlers=[
                logging.FileHandler(log_file_path),
                logging.StreamHandler(sys.stdout)
            ]
        )
        logging.info("Logging initialized to %s", log_file_path)
    except Exception as e:
        logging.error("Error setting up logging: %s", e)

# Sensor Initialization Functions
def initialize_sensor(i2c_address):
    try:
        bus = smbus2.SMBus(1)  # Use I2C bus 1 on Raspberry Pi
        sensor = adafruit_amg88xx.AMG88XX(bus, address=i2c_address)
        logging.info("Thermal sensor initialized at address 0x%x", i2c_address)
        return sensor
    except Exception as e:
        logging.error("Failed to initialize thermal sensor at address 0x%x: %s", i2c_address, e)
        raise SensorError("Failed to initialize thermal sensor") from e

# Camera Initialization Functions
def initialize_camera():
    global camera
    try:
        camera = picamera2.Picamera2()
        config = camera.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)})
        camera.configure(config)
        camera.start()
        logging.info("Camera initialized")
        return camera
    except Exception as e:
        logging.error("Failed to initialize camera: %s", e)
        return None

# Data Acquisition Functions
def read_thermal_data(sensor):
    try:
        pixels = sensor.pixels
        return np.array(pixels).reshape((8, 8))
    except Exception as e:
        logging.error("Error reading thermal data: %s", e)
        return None

# Data Storage Functions
def store_frame(frame, frame_buffer):
    with frame_buffer_lock:
        if frame_buffer is None:
            frame_buffer = np.zeros((300, 8, 8), dtype=np.float32)
        frame_buffer[:] = frame

# Data Retrieval Functions
def get_latest_frame(frame_buffer):
    with frame_buffer_lock:
        if frame_buffer is None:
            return None
        return frame_buffer[-1]

# Motion Detection Functions
def detect_motion(frame1, frame2, threshold):
    try:
        diff = np.abs(frame1 - frame2)
        mean_diff = np.mean(diff)
        return mean_diff > threshold
    except Exception as e:
        logging.error("Error detecting motion: %s", e)
        return False

# Image Capture Functions
def capture_image(camera):
    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"image_{timestamp}.jpg"
        camera.capture_file(filename)
        logging.info("Captured image: %s", filename)
        return filename
    except Exception as e:
        logging.error("Error capturing image: %s", e)
        return None

# Visualization Functions
def render_thermal_frame(frame, title):
    try:
        plt.imshow(frame, cmap='jet', interpolation='nearest')
        plt.colorbar()
        plt.title(title)
        plt.pause(0.001)  # Non-blocking pause
        plt.clf() # Clear the figure
    except Exception as e:
        logging.error("Error rendering thermal frame: %s", e)

# Signal Handlers
def signal_handler(sig, frame):
    global running
    logging.info("Received signal %s, shutting down...", sig)
    running = False

# Main Program Orchestration
def main():
    global running, config, camera, frame_buffer, frame_queue

    # Load configuration
    load_config()

    # Setup logging
    setup_logging(config['logging_file_path'])

    # Initialize sensor and camera
    try:
        sensor = initialize_sensor(0x69)  # Default I2C address
        camera = initialize_camera()
    except SensorError:
        logging.critical("Failed to initialize sensor, exiting.")
        sys.exit(1)
    except Exception as e:
        logging.critical("Failed to initialize camera, exiting: %s", e)
        sys.exit(1)

    # Start background thread for data acquisition
    def data_acquisition_thread():
        while running:
            try:
                frame = read_thermal_data(sensor)
                if frame is not None:
                    store_frame(frame, frame_buffer)
                    frame_queue.put(frame)
                time.sleep(1.0 / config['sampling_rate'])
            except Exception as e:
                logging.error("Exception in data acquisition thread: %s", e)
                time.sleep(1.0) # Prevent tight loop on error

    acquisition_thread = threading.Thread(target=data_acquisition_thread)
    acquisition_thread.daemon = True
    acquisition_thread.start()

    # Start background thread for motion detection and image capture
    def motion_detection_thread():
        global running, camera
        while running:
            try:
                frame1 = get_latest_frame(frame_buffer)
                if frame1 is None:
                    continue

                if config['enable_camera']:
                    frame2 = get_latest_frame(frame_buffer)
                    if frame2 is None:
                        continue
                    if detect_motion(frame1, frame2, config['motion_detection_threshold']):
                        logging.info("Motion detected!")
                        capture_image(camera)
                else:
                    logging.info("Motion detected (camera disabled)")

                time.sleep(0.1) # Adjust as needed
            except Exception as e:
                logging.error("Exception in motion detection thread: %s", e)
                time.sleep(1.0)

    motion_thread = threading.Thread(target=motion_detection_thread)
    motion_thread.daemon = True
    motion_thread.start()

    # Main loop for visualization
    try:
        while running:
            try:
                frame = get_latest_frame(frame_buffer)
                if frame is not None:
                    render_thermal_frame(frame, "Thermal Camera")
            except Exception as e:
                logging.error("Error in main loop: %s", e)
            time.sleep(0.1)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    finally:
        logging.info("Shutting down...")
        running = False
        if camera:
            camera.close()
        if log_file:
            log_file.close()
        logging.info("Exiting.")

# Entry Point
if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    main()

