import time
import board
import busio
import adafruit_character_lcd.character_lcd_i2c
import adafruit_dht

# Configuration
I2C_ADDRESS = 0x27
DHT_PIN = board.D4
READ_INTERVAL_SECONDS = 2

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_lcd(i2c_bus):
    """Initialize the character LCD."""
    try:
        return adafruit_character_lcd.character_lcd_i2c.Character_LCD_I2C(i2c_bus, I2C_ADDRESS)
    except Exception as e:
        print(f"Error initializing LCD: {e}")
        return None

def initialize_dht_sensor():
    """Initialize the DHT sensor."""
    try:
        return adafruit_dht.DHT22(DHT_PIN)
    except Exception as e:
        print(f"Error initializing DHT sensor: {e}")
        return None

def read_sensor_data(dht_sensor):
    """Read temperature and humidity from the DHT sensor."""
    try:
        return dht_sensor.temperature, dht_sensor.humidity
    except RuntimeError as e:
        print(f"DHT Sensor Error: {e}")
        return None, None
    except Exception as e:
        print(f"Unexpected error reading DHT sensor: {e}")
        return None, None

def display_data(lcd, temperature, humidity):
    """Display temperature and humidity on the LCD."""
    if lcd:
        try:
            lcd.clear()
            lcd.message = f"Temp: {temperature:.1f} C\nHumidity: {humidity:.1f}%"
        except Exception as e:
            print(f"Error displaying data on LCD: {e}")

def main():
    """Main function to read sensor data and display it."""
    i2c_bus = initialize_i2c()
    if not i2c_bus:
        return

    lcd_display = initialize_lcd(i2c_bus)
    if not lcd_display:
        return

    dht_sensor = initialize_dht_sensor()
    if not dht_sensor:
        return

    try:
        while True:
            temperature, humidity = read_sensor_data(dht_sensor)
            if temperature is not None and humidity is not None:
                display_data(lcd_display, temperature, humidity)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        if lcd_display:
            lcd_display.clear()

if __name__ == "__main__":
    main()

