import spidev
import time

# SPI configuration for the MAX7219 driver
SPI_BUS = 0
SPI_DEVICE = 0
SPI_CE = 8
SPI_MOSI = 10
SPI_SCLK = 11

# Initialize SPI
spi = spidev.SpiDev()
try:
    spi.open(SPI_BUS, SPI_DEVICE)
    spi.max_speed_hz = 1000000
except Exception as e:
    print(f"Error initializing SPI: {e}")
    exit(1)

# MAX7219 register addresses
REG_DECODE_MODE = 0x09
REG_INTENSITY = 0x0A
REG_SCAN_LIMIT = 0x0B
REG_SHUTDOWN = 0x0C

# Function to set the MAX7219 decode mode
def set_decode_mode(value):
    try:
        spi.xfer2([REG_DECODE_MODE, value])
    except Exception as e:
        print(f"Error setting decode mode: {e}")

# Function to set the MAX7219 intensity
def set_intensity(value):
    try:
        spi.xfer2([REG_INTENSITY, value])
    except Exception as e:
        print(f"Error setting intensity: {e}")

# Function to set the MAX7219 scan limit
def set_scan_limit(value):
    try:
        spi.xfer2([REG_SCAN_LIMIT, value])
    except Exception as e:
        print(f"Error setting scan limit: {e}")

# Function to set the MAX7219 shutdown mode
def set_shutdown(value):
    try:
        spi.xfer2([REG_SHUTDOWN, value])
    except Exception as e:
        print(f"Error setting shutdown: {e}")

# Function to build and send a frame to the LED matrix
def send_frame(frame):
    try:
        spi.xfer2([0x00] + frame)
    except Exception as e:
        print(f"Error sending frame: {e}")

# Main function to animate the alert level
def animate_alert_level():
    try:
        # Initialize the LED matrix
        set_decode_mode(0x01)  # 5x8 matrix
        set_intensity(15)      # Medium brightness
        set_scan_limit(0x07)  # Scan from left to right
        set_shutdown(0x00)    # Keep the display on

        for level in range(9):
            # Build the frame: light rows 0-7, then light rows 1-8
            frame = [0xFF] * 8 + [0x00] * 8
            send_frame(frame)
            time.sleep(0.5)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        # Clean up the SPI connection
        spi.close()

if __name__ == "__main__":
    animate_alert_level()

