import time
import board
import busio
import adafruit_ssd1306
import adafruit_dht

# Define display dimensions
DISPLAY_WIDTH = 128
DISPLAY_HEIGHT = 64

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_oled(i2c_bus):
    """Initialize the OLED display."""
    try:
        oled_display = adafruit_ssd1306.SSD1306_I2C(DISPLAY_WIDTH, DISPLAY_HEIGHT, i2c_bus)
        oled_display.fill(0)  # Clear the display
        oled_display.show()   # Update the display
        return oled_display
    except Exception as e:
        print(f"Error initializing OLED: {e}")
        return None

def read_dht22_sensor(dht_sensor):
    """Read temperature and humidity from the DHT22 sensor."""
    try:
        temperature_c = dht_sensor.temperature
        humidity_percent = dht_sensor.humidity
        return temperature_c, humidity_percent
    except RuntimeError as e:
        print(f"DHT22 sensor read error: {e}")
        return None, None
    except Exception as e:
        print(f"Unexpected error reading DHT22 sensor: {e}")
        return None, None

def display_data(oled, temperature, humidity):
    """Display temperature and humidity on the OLED screen."""
    try:
        oled.fill(0)  # Clear the display
        oled.text(f"Temp: {temperature:.1f} C", 0, 0, 1)
        oled.text(f"Humidity: {humidity:.1f} %", 0, 16, 1)
        oled.show()   # Update the display
    except Exception as e:
        print(f"Error displaying data on OLED: {e}")

def main():
    """Main function to read sensor data and display it."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    oled_display = initialize_oled(i2c_bus)
    if oled_display is None:
        return

    dht_sensor = adafruit_dht.DHT22(board.D4) # Using board.D4 as specified

    try:
        while True:
            temperature, humidity = read_dht22_sensor(dht_sensor)

            if temperature is not None and humidity is not None:
                display_data(oled_display, temperature, humidity)
            else:
                print("Failed to retrieve data from DHT22 sensor.")

            time.sleep(2)  # Wait for 2 seconds

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        # Clear the OLED display before exiting
        oled_display.fill(0)
        oled_display.show()
        print("OLED cleared.")

if __name__ == "__main__":
    main()

