import time
import smbus2
import RPi.GPIO as GPIO

# I2C address of the PCF8574 expander
PCF8574_ADDRESS = 0x20

# Initialize I2C bus
try:
    i2c_bus = smbus2.SMBus(1)  # Use 1 for Raspberry Pi 3 and later
except Exception as e:
    print(f"Error initializing I2C bus: {e}")
    exit(1)

# PCF8574 register map
REG_OUTPUT = 0x00
REG_INPUT = 0x01
REG_LOCK = 0x07
REG_MODE = 0x00  # Mode register for input-only operation

# Configure the expander as an input device with internal pull-up enabled
try:
    i2c_bus.write_byte_data(PCF8574_ADDRESS, REG_MODE, 0x00)  # Input mode
    i2c_bus.write_byte_data(PCF8574_ADDRESS, REG_LOCK, 0xFF)  # Enable internal pull-up
except Exception as e:
    print(f"Error configuring PCF8574: {e}")
    exit(1)


def read_sensor_value(sensor_pin):
    """Read the state of a specific sensor pin."""
    try:
        return i2c_bus.read_byte_data(PCF8574_ADDRESS, sensor_pin)
    except Exception as e:
        print(f"Error reading sensor {sensor_pin}: {e}")
        return None


def main():
    """Main function to monitor proximity sensors."""
    try:
        while True:
            for sensor_index in range(8):
                sensor_value = read_sensor_value(sensor_index * 2)  # Each sensor is 2 bits wide
                if sensor_value is not None:
                    if sensor_value == 0xFF:  # Active-low sensor (LOW indicates obstacle)
                        print(f"Obstacle detected by sensor {sensor_index}")
            time.sleep(0.1)  # Polling interval

    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # No specific cleanup needed for smbus2, but good practice to include GPIO cleanup
        GPIO.cleanup()


if __name__ == "__main__":
    main()

