import paho.mqtt.client as mqtt
import time
import json
import random
import logging
from threading import Thread, Lock
from typing import Callable, Any

# Configure logging for the classroom MQTT publisher
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants for the demonstration
BROKER_HOST = "test.mosquitto.org"
BROKER_PORT = 1883
TEMPERATURE_TOPIC = "classroom/temperature"
NUM_MESSAGES = 5
KEEPALIVE_INTERVAL = 60  # seconds
RETRY_DELAY = 2  # seconds
MAX_RETRIES = 3


def generate_temperature() -> float:
    """Generates a random temperature between 19.0 and 26.0 degrees Celsius."""
    return round(random.uniform(19.0, 26.0), 2)


def build_payload(index: int, temperature: float) -> str:
    """Builds a JSON payload with the given index and temperature."""
    return json.dumps({"index": index, "temperature": temperature})


def on_connect(client: mqtt.Client, userdata: Any, flags: int, rc: int) -> None:
    """Callback function for when the client connects to the broker."""
    if rc == 0:
        logging.info("Connected to MQTT Broker!")
        client.subscribe(TEMPERATURE_TOPIC)
    else:
        logging.error(f"Failed to connect, return code {rc}")



def on_publish(client: mqtt.Client, userdata: Any, mid: int) -> None:
    """Callback function for when a message is published."""
    logging.info(f"Message published with ID {mid}")


def publish_message(client: mqtt.Client, topic: str, payload: str) -> None:
    """Publishes a message to the specified topic."""
    try:
        client.publish(topic, payload)
        logging.info(f"Published: {payload} to topic: {topic}")
    except Exception as e:
        logging.error(f"Failed to publish message: {e}")


def publish_temperature_series(client: mqtt.Client, topic: str, num_messages: int) -> None:
    """Publishes a series of temperature readings."""
    temperatures = [generate_temperature() for _ in range(num_messages)]
    for i, temperature in enumerate(temperatures):
        payload = build_payload(i, temperature)
        publish_message(client, topic, payload)


def connect_and_publish(client: mqtt.Client, topic: str, num_messages: int) -> None:
    """Connects to the broker, publishes messages, and handles errors."""
    global connected  # Use global connected to access its value

    for attempt in range(MAX_RETRIES):
        try:
            client.connect(BROKER_HOST, BROKER_PORT, KEEPALIVE_INTERVAL)
            client.loop_start()  # Start the MQTT loop in the background
            publish_temperature_series(client, topic, num_messages)
            connected.set()  # Signal connection success
            return  # Exit the function if successful
        except Exception as e:
            logging.error(f"Attempt {attempt + 1} failed: {e}")
            if attempt < MAX_RETRIES - 1:
                time.sleep(RETRY_DELAY)
    logging.error("Failed to connect and publish after multiple retries.")


def safe_disconnect(client: mqtt.Client) -> None:
    """Disconnects the client safely, handling potential exceptions."""
    try:
        client.loop_stop()  # Stop the MQTT loop
        client.disconnect()
        logging.info("Disconnected from MQTT broker.")
    except Exception as e:
        logging.error(f"Error during disconnection: {e}")


def main() -> None:
    """Main function to run the MQTT publisher."""
    connected = False  # Global flag to track connection status

    client = mqtt.Client()
    client.on_connect = on_connect
    client.on_publish = on_publish

    try:
        connect_and_publish(client, TEMPERATURE_TOPIC, NUM_MESSAGES)
        if connected:
            print(f"Published {NUM_MESSAGES} messages to {TEMPERATURE_TOPIC}")
    except KeyboardInterrupt:
        logging.info("Interrupted by user. Disconnecting...")
        safe_disconnect(client)


if __name__ == "__main__":
    main()

