import serial
import time
import csv
import os

# Serial port configuration
SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
TIMEOUT = 1

# CSV log file path
LOG_FILE = 'temperature_log.csv'

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_temperature(serial_connection):
    """Reads a temperature value from the serial port."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Invalid data received from sensor.")
        return None
    except Exception as e:
        print(f"Error reading from serial port: {e}")
        return None

def convert_to_fahrenheit(celsius):
    """Converts Celsius to Fahrenheit."""
    return (celsius * 9/5) + 32

def log_temperature(timestamp, celsius, fahrenheit, log_file):
    """Logs the temperature data to a CSV file."""
    try:
        with open(log_file, 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow([timestamp, celsius, fahrenheit])
    except IOError as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to read and log temperature data."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.")
        return

    try:
        # Write header if the file doesn't exist
        if not os.path.exists(LOG_FILE):
            with open(LOG_FILE, 'w', newline='') as csvfile:
                writer = csv.writer(csvfile)
                writer.writerow(['timestamp', 'celsius', 'fahrenheit'])

        while True:
            temperature = read_temperature(serial_connection)
            if temperature is not None:
                fahrenheit = convert_to_fahrenheit(temperature)
                timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
                log_temperature(timestamp, temperature, fahrenheit, LOG_FILE)
                print(f"Timestamp: {timestamp}, Temperature: {temperature:.2f}C, {fahrenheit:.2f}F")

            time.sleep(1)

    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

