# Raspberry Pi 4 BMP280 Barometric Pressure and Altitude Logger
# Reads pressure and altitude from a BMP280 sensor via I2C.
# Designed for a classroom demonstration.

import time
import board
import busio
import adafruit_bmp280

# BMP280 I2C address and sea level pressure (in hPa)
BMP280_I2C_ADDRESS = 0x76
SEA_LEVEL_PRESSURE = 1013.25

def initialize_sensor():
    """Initializes the BMP280 sensor."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        bmp280 = adafruit_bmp280.BMP280_I2C(i2c_bus, address=BMP280_I2C_ADDRESS)
        bmp280.sea_level_pressure = SEA_LEVEL_PRESSURE
        return bmp280
    except Exception as e:
        print(f"Error initializing BMP280: {e}")
        return None

def read_sensor_data(sensor):
    """Reads pressure and altitude from the BMP280 sensor."""
    if sensor is None:
        return None, None
    try:
        pressure = sensor.pressure
        altitude = sensor.altitude
        return pressure, altitude
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None

def log_data(pressure, altitude):
    """Logs the pressure and altitude data to a file."""
    if pressure is not None and altitude is not None:
        timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
        log_entry = f"{timestamp} - Pressure: {pressure:.2f} hPa, Altitude: {altitude:.2f} meters\n"
        try:
            with open("altitude_log.txt", "a") as log_file:
                log_file.write(log_entry)
        except Exception as e:
            print(f"Error writing to log file: {e}")

def main():
    """Main function to read and log sensor data."""
    sensor = initialize_sensor()
    if sensor is None:
        print("Failed to initialize sensor. Exiting.")
        return

    try:
        while True:
            pressure, altitude = read_sensor_data(sensor)
            if pressure is not None and altitude is not None:
                print(f"Pressure: {pressure:.2f} hPa, Altitude: {altitude:.2f} meters")
                log_data(pressure, altitude)
            time.sleep(1)  # Wait for 1 second
    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

