import time
import json
import requests
import board
import adafruit_dht

# Configuration
SERVER_URL = 'http://127.0.0.1:5000/data'
SLEEP_INTERVAL = 5  # seconds

# Initialize DHT sensor
dht_sensor = adafruit_dht.DHT11(board.D4)

def get_sensor_data():
    """Reads temperature and humidity from the DHT sensor."""
    try:
        temperature = dht_sensor.temperature
        humidity = dht_sensor.humidity
        return temperature, humidity
    except RuntimeError as error:
        # DHT11 sensor sometimes returns errors, handle them gracefully
        print(f"DHT11 Error: {error}")
        return None, None

def send_data_to_server(temperature, humidity):
    """Sends the temperature and humidity data to the server."""
    if temperature is not None and humidity is not None:
        data = {"temperature": temperature, "humidity": humidity}
        try:
            response = requests.post(SERVER_URL, json=data)
            print(f"Server response: {response.status_code}")
        except requests.exceptions.RequestException as e:
            print(f"Network error: {e}")
    else:
        print("Invalid sensor data, skipping send.")

def main():
    """Main function to read sensor data and send it to the server."""
    try:
        while True:
            temperature, humidity = get_sensor_data()
            send_data_to_server(temperature, humidity)
            time.sleep(SLEEP_INTERVAL)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        # No specific cleanup needed for DHT11 or requests, but good practice to include a finally block
        print("Program finished.")

if __name__ == "__main__":
    main()

