def read_dht22_data():
    """Reads temperature and humidity from the DHT22 sensor."""
    try:
        dht_device = adafruit_dht.DHT22(DHT_PIN)
        temperature_c = dht_device.temperature
        humidity_percent = dht_device.humidity
        return temperature_c, humidity_percent
    except RuntimeError as error:
        # Errors happen fairly often, DHT's are hard to read, just keep going
        print(f"DHT Sensor RuntimeError: {error}")
        return None, None
    except Exception as error:
        print(f"Unexpected error reading DHT sensor: {error}")
        return None, None

def format_reading(temperature, humidity):
    """Formats the temperature and humidity readings with a timestamp."""
    timestamp = datetime.now().isoformat()
    if temperature is not None and humidity is not None:
        return f"{timestamp} Temp: {temperature:.1f}°C Humidity: {humidity:.1f}%"
    else:
        return None

def main():
    """Main function to read and print DHT22 sensor data."""
    try:
        while True:
            temperature, humidity = read_dht22_data()
            if temperature is not None and humidity is not None:
                print(format_reading(temperature, humidity))
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

