import time
import board
import busio
import adafruit_seesaw.seesaw
import RPi.GPIO as GPIO
from gpiozero import OutputDevice

# Configuration constants
I2C_ADDRESS = 0x36
PUMP_GPIO_PIN = 17
DRY_THRESHOLD = 300
READ_INTERVAL_SECONDS = 10

# Initialize I2C bus
try:
    i2c_bus = busio.I2C(board.SCL, board.SDA)
except ValueError as e:
    print(f"Error initializing I2C: {e}")
    exit(1)

# Initialize the soil moisture sensor
try:
    soil_sensor = adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=I2C_ADDRESS)
except ValueError as e:
    print(f"Error initializing soil sensor: {e}")
    exit(1)

# Initialize the water pump control
try:
    pump = OutputDevice(PUMP_GPIO_PIN, active_high=True, initial_value=False)
except Exception as e:
    print(f"Error initializing pump: {e}")
    exit(1)


def read_soil_moisture():
    """Reads the soil moisture level from the sensor."""
    try:
        moisture_level = soil_sensor.moisture_read()
        return moisture_level
    except Exception as e:
        print(f"Error reading soil moisture: {e}")
        return None


def control_water_pump(moisture_level):
    """Controls the water pump based on the soil moisture level."""
    try:
        if moisture_level is not None:
            if moisture_level < DRY_THRESHOLD:
                pump.on()
                print("Water Pump ON: Soil too dry")
            else:
                pump.off()
                print("Water Pump OFF: Soil moisture sufficient")
    except Exception as e:
        print(f"Error controlling pump: {e}")


def main_loop():
    """Main loop to read sensor data and control the pump."""
    try:
        while True:
            moisture = read_soil_moisture()
            control_water_pump(moisture)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure pump is off and GPIO is cleaned up
        pump.off()
        GPIO.cleanup()
        print("GPIO cleaned up. Exiting.")


if __name__ == "__main__":
    main_loop()

