import time
import signal
import sys
import logging
from typing import List, Tuple

try:
    from gpiozero import OutputDevice, InputDevice
except ImportError:
    # Dummy gpiozero imports for testing on systems without gpiozero
    class OutputDevice:
        def __init__(self, pin: int):
            pass

        def on(self):
            pass

        def off(self):
            pass

    class InputDevice:
        def __init__(self, pin: int):
            pass

        def is_active(self):
            return True

        def wait_for_edge(self, edge_type: str = 'rising', timeout: float = None):
            pass

    START_SIGNAL = b'\x1A'
    END_SIGNAL = b'\x7E'
    DATA_OUT_PIN = 5
    TIMER_OUT_PIN = 6
    DATA_IN_PIN = 20
    TIMER_IN_PIN = 21
    TRANSMIT_DELAY = 0.0005
    MAX_RETRIES = 3
    RECEPTION_TIMEOUT = 1  # seconds


# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


def initialize_gpio():
    """Initializes GPIO pins using gpiozero. Handles potential errors."""
    try:
        data_out = OutputDevice(DATA_OUT_PIN)
        timer_out = OutputDevice(TIMER_OUT_PIN)
        data_in = InputDevice(DATA_IN_PIN)
        timer_in = InputDevice(TIMER_IN_PIN)
        return data_out, timer_out, data_in, timer_in
    except Exception as e:
        logging.error(f"GPIO initialization failed: {e}")
        sys.exit(1)


def transmit_bit(data_out: OutputDevice, timer_out: OutputDevice, bit: bool):
    """Transmits a single bit."""
    try:
        if bit:
            data_out.on()
            timer_out.on()
            time.sleep(TRANSMIT_DELAY)
            data_out.off()
            timer_out.off()
        else:
            data_out.off()
            timer_out.off()
    except Exception as e:
        logging.error(f"Error transmitting bit: {e}")
        raise  # Re-raise the exception to be handled at a higher level


def transmit_string(data_out: OutputDevice, timer_out: OutputDevice, string: str):
    """Transmits a string over the data protocol."""
    try:
        for char in string:
            for bit in range(8):
                bit_value = (ord(char) >> bit) & 1
                transmit_bit(data_out, timer_out, bit_value)
                time.sleep(TRANSMIT_DELAY)
            time.sleep(0.001)  # Small delay between characters
        logging.info(f"Transmitted string: {string}")
    except Exception as e:
        logging.error(f"Error transmitting string: {e}")
        raise


def receive_bit(data_in: InputDevice, timer_in: InputDevice, retries: int = MAX_RETRIES):
    """Receives a single bit with retries."""
    for _ in range(retries):
        if data_in.is_active():
            return True
        time.sleep(0.0001)
    return False


def receive_string(data_in: InputDevice, timer_in: InputDevice):
    """Receives a string over the data protocol."""
    try:
        received_string = ""
        current_char = ""

        while True:
            for bit in range(8):
                if receive_bit(data_in, timer_in):
                    current_char += (0 if bit == 0 else 1) * (chr(bit) + 1)
                    if len(current_char) == 8:
                        received_string += current_char
                        current_char = ""
                time.sleep(TRANSMIT_DELAY)

        logging.info(f"Received string: {received_string}")
        return received_string
    except Exception as e:
        logging.error(f"Error receiving string: {e}")
        return ""



def safe_receive_string(data_in: InputDevice, timer_in: InputDevice, timeout: float):
    """Receives a string with a timeout."""
    start_time = time.time()
    received_string = ""
    while time.time() - start_time < timeout and receive_bit(data_in, timer_in):
        for bit in range(8):
            if receive_bit(data_in, timer_in):
                current_char = (0 if bit == 0 else 1) * (chr(bit) + 1)
                if len(current_char) == 8:
                    received_string += current_char
                    current_char = ""
        time.sleep(TRANSMIT_DELAY)

    logging.info(f"Received string (timeout): {received_string}")
    return received_string


def main():
    """Main function for the data protocol communicator."""

    signal.signal(signal.SIGINT, lambda *args: sys.exit(0))  # Graceful shutdown
    signal.signal(signal.SIGTERM, lambda *args: sys.exit(0))

    data_out, timer_out, data_in, timer_in = initialize_gpio()

    try:
        while True:
            action = input("Enter command (s: send, r: receive, q: quit): ").lower()

            if action == 's':
                string = input("Enter string to send: ")
                transmit_string(data_out, timer_out, string)
            elif action == 'r':
                print("Receiving data...")
                received_string = safe_receive_string(data_in, timer_in, RECEPTION_TIMEOUT)
                if received_string:
                    print(f"Received: {received_string}")
                else:
                    print("Timeout or error receiving data.")
            elif action == 'q':
                break
            else:
                print("Invalid command.")

    except Exception as e:
        logging.exception(f"An unexpected error occurred: {e}")
    finally:
        logging.info("Cleaning up GPIO...")
        data_out.off()
        timer_out.off()
        data_in.close()
        timer_in.close()
        logging.info("Exiting.")


if __name__ == "__main__":
    main()

