import time
import board
import busio
import adafruit_fingerprint

# Define constants
I2C_ADDRESS = 0x26
DATABASE_FILE = "fingerprints.txt"  # Replace with your actual database file

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_fingerprint(i2c_bus):
    """Initializes the fingerprint sensor."""
    try:
        return adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
    except Exception as e:
        print(f"Error initializing fingerprint sensor: {e}")
        return None

def load_database(filename):
    """Loads the fingerprint database from a file."""
    try:
        with open(filename, "r") as f:
            return [line.strip() for line in f]
    except FileNotFoundError:
        print(f"Database file not found: {filename}")
        return []
    except Exception as e:
        print(f"Error loading database: {e}")
        return []

def save_database(filename, name):
    """Saves the fingerprint database to a file."""
    try:
        with open(filename, "w") as f:
            f.write(f"{name}\n")
    except Exception as e:
        print(f"Error saving database: {e}")

def authenticate(fingerprint_sensor, database):
    """Authenticates a fingerprint against the database."""
    try:
        print("Waiting for finger...")
        while True:
            print("-" * 50)
            time.sleep(0.1)  # Reduced wait time
            if fingerprint_sensor.get_image():
                print("-" * 50)
                print("Templating...")
                if fingerprint_sensor.image_2_tz(1):
                    print("-" * 50)
                    print("Searching...")
                    if fingerprint_sensor.finger_search():
                        print("-" * 50)
                        print(f"Access Granted for {database[0]}")
                        return True
                    else:
                        print("-" * 50)
                        print("No match found.")
                        return False
                else:
                    print("-" * 50)
                    print("Templating failed.")
                    return False
    except RuntimeError as e:
        print(f"RuntimeError during authentication: {e}")
        return False
    except Exception as e:
        print(f"Unexpected error during authentication: {e}")
        return False

def main():
    """Main function for fingerprint authentication."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    fingerprint_sensor = initialize_fingerprint(i2c_bus)
    if fingerprint_sensor is None:
        return

    # Initialize fingerprint database
    if not fingerprint_sensor.load():
        print("Error initializing fingerprint sensor.  Please check connection.")
        return

    database = load_database(DATABASE_FILE)

    try:
        while True:
            authenticate(fingerprint_sensor, database)
            time.sleep(1)  # Reduced delay
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        i2c_bus.deinit()
        print("I2C bus deinitialized.")

if __name__ == "__main__":
    main()

