import random
import json

# Define the actions for the smart agriculture system
actions = {
    'water': 'open_valve',
    'stop': 'close_valve',
    'status': 'report'
}

# Function to simulate audio frame generation
def generate_audio_frame():
    """Simulates generating an audio frame with a random energy level."""
    return random.randint(0, 9)

# Function to simulate voice recognition
def recognize_voice(frame):
    """Simulates voice recognition by mapping energy level to a keyword."""
    energy = frame['energy']
    if energy % 3 == 0:
        return 'water'
    elif energy % 3 == 1:
        return 'stop'
    else:
        return 'status'

# Function to perform farm action
def perform_action(action):
    """Performs the corresponding farm action based on the recognized keyword."""
    if action == 'water':
        print('Opening the water valve.')
    elif action == 'stop':
        print('Stopping the water flow.')
    elif action == 'status':
        print('Reporting the water level.')

# Main function to run the smart agriculture voice recognition system
def main():
    """Runs the smart agriculture voice recognition system simulation."""
    try:
        # Simulate 6 audio frames
        for i in range(6):
            # Generate a simulated audio frame
            frame = {'energy': generate_audio_frame()}

            # Recognize the voice command
            word = recognize_voice(frame)

            # Perform the corresponding farm action
            perform_action(word)

            # Print the frame index, transcribed word, and performed action
            print(f'Frame {i}: Word = {word}, Action = {actions[word]}')

            # Wait for 1 second
