import time
import json
import requests
from gpiozero import Button

# Configuration for the quality control system
BUTTON_PIN = 17
SERVER_URL = "http://localhost:8000/quality"
PART_ID = 'PART-204'

# Initialize the button with a pull-up resistor
button = Button(BUTTON_PIN, pull_up=True)

def get_inspection_result():
    """Return True when the button is pressed, False otherwise."""
    return button.is_pressed

def build_report(passed, defect_count):
    """Create a JSON report with the inspection result and defect count."""
    return json.dumps({"part_id": PART_ID, "passed": passed, "defect_count": defect_count})

def submit_report(report):
    """Send the report to the server and return the status code."""
    try:
        response = requests.post(SERVER_URL, data=report, headers={'Content-Type': 'application/json'})
        return response.status_code
    except requests.exceptions.RequestException as e:
        print(f"Network error: {e}")
        return None

def main():
    """Main function to continuously monitor the button and submit reports."""
    try:
        while True:
            inspection_result = get_inspection_result()
            if inspection_result:
                # Simulate a failed inspection
                report = build_report(False, 1)
                status_code = submit_report(report)
                if status_code:
                    print(f"Report submitted. Status code: {status_code}")
                else:
                    print("Failed to submit report.")
            else:
                # Simulate a passing inspection
                report = build_report(True, 0)
                status_code = submit_report(report)
                if status_code:
