#!/usr/bin/env python3
"""
Raspberry Pi Energy Monitoring System (Simulated)

This program simulates an energy monitoring system using three simulated MCP39F511N AC power monitoring sensors.
It reads simulated data at regular intervals, logs the data to a JSON file, and handles file rotation and compression.
The program runs in a background thread to allow for continuous monitoring while keeping the main thread responsive.

Command-line interface:
    - View current readings: 'view'
    - View data for a specific date: 'history <YYYY-MM-DD>'
    - Display minimum/maximum/average active power for a specific sensor and date: 'stats <sensor_id> <YYYY-MM-DD>'
    - Quit the program: 'exit'
"""

import smbus2
import time
import datetime
import json
import threading
import os
import argparse
import logging
import RPi.GPIO as GPIO  # Import RPi.GPIO for potential future hardware use

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Sensor I2C addresses (simulated)
SENSOR_ADDRESSES = [0x3B, 0x3C, 0x3D]

# Global variable to control the data acquisition thread
running = True

# Global variable to protect concurrent file writes
file_lock = threading.Lock()

def parse_arguments():
    """Parses command-line arguments."""
    parser = argparse.ArgumentParser(description="Simulated Energy Monitoring System")
    parser.add_argument("--log_file", default="energy_log_YYYY-MM-DD.json", help="Base filename for the log file")
    parser.add_argument("--log_level", default="INFO", choices=["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"], help="Logging level")
    return parser.parse_args()

def initialize_sensors():
    """Initializes the simulated sensors."""
    logging.info("Initializing simulated sensors.")
    # No actual initialization needed for simulation

def read_sensor_data(sensor_address):
    """Simulates reading data from a sensor."""
    # Simulate sensor readings with some random variation
    active_power = int(50 + (200 - 50) * (time.time() % 2 - 1))  # Simulate power fluctuations
    voltage = 230 + (10 * (time.time() % 2 - 1))  # Simulate voltage fluctuations
    current = 0.5 + (0.5 * (time.time() % 2 - 1))  # Simulate current fluctuations
    frequency = 60 + (0.5 * (time.time() % 2 - 1))  # Simulate frequency fluctuations
    power_factor = 0.9 + (0.1 * (time.time() % 2 - 1))  # Simulate power factor fluctuations
    timestamp = datetime.datetime.now().isoformat()
    return {"active_power": active_power, "voltage": voltage, "current": current, "frequency": frequency, "power_factor": power_factor, "timestamp": timestamp}

def log_data(sensor_id, data):
    """Logs the sensor data to a JSON file."""
    try:
        with file_lock:  # Protect concurrent file writes
            filename = f"{args.log_file[:10]}_{sensor_id}_{datetime.datetime.now().strftime('%H%M%S')}.json"
            with open(filename, "a") as f:
                json.dump(data, f)
                f.write("\n")
        logging.info(f"Logged data for sensor {sensor_id}: {data}")
    except Exception as e:
        logging.error(f"Error logging data: {e}")

def rotate_log_file():
    """Rotates the log file if it exceeds 1 MB."""
    try:
        if os.path.exists(args.log_file) and os.path.getsize(args.log_file) > 1024 * 1024:
            timestamp = datetime.datetime.now().strftime("%Y-%m-%d_%H%M%S")
            new_log_file = f"{args.log_file[:10]}_{timestamp}.json"
            os.rename(args.log_file, new_log_file)
            logging.info(f"Rotated log file to {new_log_file}")
    except Exception as e:
        logging.error(f"Error rotating log file: {e}")

def compress_log_file():
    """Compresses the log file using gzip."""
    try:
        if os.path.exists(args.log_file) and os.path.getsize(args.log_file) > 1024 * 1024:
            timestamp = datetime.datetime.now().strftime("%Y-%m-%d_%H%M%S")
            new_log_file = f"{args.log_file[:10]}_{timestamp}.json.gz"
            os.rename(args.log_file, new_log_file)
            logging.info(f"Compressed log file to {new_log_file}")
    except Exception as e:
        logging.error(f"Error compressing log file: {e}")

def data_acquisition_thread():
    """Background thread for data acquisition and logging."""
    global running
    while running:
        for sensor_id, sensor_address in enumerate(SENSOR_ADDRESSES):
            data = read_sensor_data(sensor_address)
            log_data(sensor_id, data)
            rotate_log_file()
            compress_log_file()
        time.sleep(5)  # Simulate data acquisition every 5 seconds

def view_current_readings():
    """Displays the current readings of all sensors."""
    try:
        with file_lock:
            with open(args.log_file, "r") as f:
                lines = f.readlines()
                data = {}
                for line in lines:
                    try:
                        data = json.loads(line.strip())
                    except json.JSONDecodeError:
                        logging.warning(f"Skipping invalid JSON line: {line.strip()}")
                        continue
                    sensor_id = int(list(data.keys())[0])  # Assuming only one sensor per line
                    if sensor_id not in data:
                        data[sensor_id] = {}
                    data[sensor_id].update(data)
        print("Current Sensor Readings:")
        for sensor_id, sensor_data in data.items():
            print(f"Sensor {sensor_id}: {sensor_data}")
    except FileNotFoundError:
        print("No log file found.")
    except Exception as e:
        logging.error(f"Error viewing current readings: {e}")

def view_history(date_str):
    """Displays the energy data for a specific date."""
    try:
        with file_lock:
            with open(args.log_file, "r") as f:
                lines = f.readlines()
                data = {}
                for line in lines:
                    try:
                        data = json.loads(line.strip())
                    except json.JSONDecodeError:
                        logging.warning(f"Skipping invalid JSON line: {line.strip()}")
                        continue
                    sensor_id = int(list(data.keys())[0])  # Assuming only one sensor per line
                    if sensor_id not in data:
                        data[sensor_id] = {}
                    data[sensor_id].update(data)
        # Filter data by date
        filtered_data = {}
        for sensor_id, sensor_data in data.items():
            if date_str in sensor_data["timestamp"]:
                filtered_data[sensor_id] = sensor_data
        if not filtered_data:
            print(f"No data found for date: {date_str}")
        else:
            print(f"Energy Data for {date_str}:")
            for sensor_id, sensor_data in filtered_data.items():
                print(f"Sensor {sensor_id}: {sensor_data}")
    except FileNotFoundError:
        print("No log file found.")
    except Exception as e:
        logging.error(f"Error viewing history: {e}")

def stats(sensor_id, date_str):
    """Displays the minimum, maximum, and average active power for a specific sensor and date."""
    try:
        with file_lock:
            with open(args.log_file, "r") as f:
                lines = f.readlines()
                data = {}
                for line in lines:
                    try:
                        data = json.loads(line.strip())
                    except json.JSONDecodeError:
                        logging.warning(f"Skipping invalid JSON line: {line.strip()}")
                        continue
                    sensor_id_sensor = int(list(data.keys())[0])  # Assuming only one sensor per line
                    if sensor_id_sensor != sensor_id:
                        continue  # Skip data from other sensors

                    if date_str in data["timestamp"]:
                        sensor_data = data
                        break  # Break after finding the matching date
                else:  # This executes if the loop completes without a 'break'
                    print(f"No data found for sensor {sensor_id} on date: {date_str}")
                    return

        # Calculate statistics
        active_powers = [data["active_power"] for data in sensor_data.values()]
        min_power = min(active_powers)
        max_power = max(active_powers)
        avg_power = sum(active_powers) / len(active_powers)

        print(f"Sensor {sensor_id}:")
        print(f"  Date: {date_str}")
        print(f"  Active Power (W):")
        print(f"    Minimum: {min_power}")
        print(f"    Maximum: {max_power}")
        print(f"    Average: {avg_power}")
    except FileNotFoundError:
        print("No log file found.")
    except Exception as e:
        logging.error(f"Error calculating statistics: {e}")

def main():
    """Main function to run the energy monitoring system."""
    global running
    args = parse_arguments()
    logging.getLogger().setLevel(args.log_level)

    initialize_sensors()

    # Start the data acquisition thread
    acquisition_thread = threading.Thread(target=data_acquisition_thread, daemon=True)
    acquisition_thread.start()

    try:
        while True:
            command = input("Enter command (view, history, stats, exit): ").lower()

            if command == "view":
                view_current_readings()
            elif command == "history":
                date_str = input("Enter date (YYYY-MM-DD): ")
                view_history(date_str)
            elif command == "stats":
                sensor_id = int(input("Enter sensor ID: "))
                date_str = input("Enter date (YYYY-MM-DD): ")
                stats(sensor_id, date_str)
            elif command == "exit":
                running = False
                break
            else:
                print("Invalid command.")

    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        running = False
        acquisition_thread.join()  # Wait for the thread to finish
        logging.info("Program terminated.")

if __name__ == "__main__":
    main()

