import time
import signal
import sys
from gpiozero import AngularServo
from functools import partial

# Constants for GPIO pins and servo parameters
BASE_PIN = 17
SHOULDER_PIN = 27
GRIPPER_PIN = 22
PWM_FREQUENCY = 50
MIN_PULSE_WIDTH = 0.5  # ms
MAX_PULSE_WIDTH = 2.5  # ms
SETTLING_TIME = 0.4  # seconds

# Global variable to track program running state
running = True

def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    global running
    print("Exiting gracefully...")
    running = False
    servo_release(robot_arm)  # Release servos before exiting
    sys.exit(0)

def clamp_angle(angle, min_angle=-90, max_angle=90):
    """Clamps the angle within the specified range."""
    return max(min_angle, min(angle, max_angle))

def move_joint(servo, target_angle, settling_time=SETTLING_TIME):
    """Moves a servo to the target angle with settling time."""
    try:
        servo.angle = target_angle
        time.sleep(settling_time)
    except Exception as e:
        print(f"Error moving servo: {e}")

def move_servo(servo, angle):
    """Moves a servo to the specified angle, handling potential errors."""
    try:
        move_joint(servo, angle)
    except Exception as e:
        print(f"Error moving servo on pin {servo.pin}: {e}")

def create_servo(pin, min_pulse_width=MIN_PULSE_WIDTH, max_pulse_width=MAX_PULSE_WIDTH):
    """Creates and initializes an AngularServo object."""
    try:
        servo = AngularServo(pin, min_pulse_width=min_pulse_width, max_pulse_width=max_pulse_width, frequency=PWM_FREQUENCY)
        servo.angle = 0  # Initialize to 0 degrees
        return servo
    except Exception as e:
        print(f"Error creating servo on pin {pin}: {e}")
        return None

def move_servo_with_error_handling(servo, angle):
    """Moves a servo with error handling."""
    if servo is None:
        print(f"Servo on pin {servo.pin} is not initialized.")
        return

    try:
        move_joint(servo, angle)
    except Exception as e:
        print(f"Error moving servo on pin {servo.pin}: {e}")


def go_to_pose(robot_arm, base_angle, shoulder_angle, gripper_angle):
    """Moves the robotic arm to a specific pose."""
    try:
        move_servo_with_error_handling(robot_arm.base, clamp_angle(base_angle))
        move_servo_with_error_handling(robot_arm.shoulder, clamp_angle(shoulder_angle))
        move_servo_with_error_handling(robot_arm.gripper, clamp_angle(gripper_angle))
    except Exception as e:
        print(f"Error going to pose: {e}")


def release_servos(robot_arm):
    """Releases all servos."""
    try:
        for servo in robot_arm.servos:
            move_servo_with_error_handling(servo, 0)  # Move to 0 degrees
    except Exception as e:
        print(f"Error releasing servos: {e}")


class RoboticArm:
    """Controls a robotic arm with multiple servos."""

    def __init__(self, base_pin=BASE_PIN, shoulder_pin=SHOULDER_PIN, gripper_pin=GRIPPER_PIN):
        """Initializes the robotic arm with servo control."""

        self.base_pin = base_pin
        self.shoulder_pin = shoulder_pin
        self.gripper_pin = gripper_pin

        self.base = create_servo(self.base_pin)
        self.shoulder = create_servo(self.shoulder_pin)
        self.gripper = create_servo(self.gripper_pin)

        if not all(servo for servo in [self.base, self.shoulder, self.gripper]):
            raise ValueError("One or more servo creations failed. Check GPIO pin availability.")


        self.servos = [self.base, self.shoulder, self.gripper]  # List for easier iteration
        self.angle_limits = [-90, 90]  # Define angle limits


    def move_joint(self, joint_name, target_angle):
        """Moves a specific joint to the target angle."""
        if joint_name not in ["base", "shoulder", "gripper"]:
            raise ValueError("Invalid joint name. Must be 'base', 'shoulder', or 'gripper'.")


        try:
            angle_index = self.angle_limits.index(clamp_angle(target_angle))
        except ValueError:
            raise ValueError(f"Target angle {target_angle} is out of range. Angle limits are {self.angle_limits}")


        if joint_name == "base":
            servo = self.base
        elif joint_name == "shoulder":
            servo = self.shoulder
        else:
            servo = self.gripper

        move_servo_with_error_handling(servo, angle_index)


    def go_to_pose(self, base_angle, shoulder_angle, gripper_angle):
        """Moves the arm to a specific pose."""
        go_to_pose(self, base_angle, shoulder_angle, gripper_angle)


    def release(self):
        """Releases all servo motors."""
        release_servos(self)


def run_demo_sequence(robot_arm):
    """Runs a predefined demo sequence for the robotic arm."""

    poses = [
        (0, 0, 0),  # Start
        (45, -30, 20),  # Reach down
        (-45, 30, -20),  # Reach up
        (0, 0, 0)  # Return to start
    ]

    try:
        for base_angle, shoulder_angle, gripper_angle in poses:
            print(f"Moving to pose: Base={base_angle}, Shoulder={shoulder_angle}, Gripper={gripper_angle}")
            robot_arm.go_to_pose(base_angle, shoulder_angle, gripper_angle)
