# Constants for garage door states
DOOR_CLOSED = "closed"
DOOR_OPEN = "open"

def initialize_garage_door(state_pin):
    """Initializes the garage door object with the given state pin."""
    try:
        if not isinstance(state_pin, int) or not 0 <= state_pin <= 3:
            raise ValueError("State pin must be an integer between 0 and 3")
        logging.info(f"Garage door initialized with state pin: {state_pin}")
        return GarageDoor(state_pin)
    except ValueError as e:
        logging.error(f"Invalid state pin: {e}")
        return None

def read_state(pin):
    """Reads the state of the given pin."""
    try:
        return automationhat.input[pin].read() == automationhat.input[pin].READ_HIGH
    except IndexError:
        logging.error(f"Invalid pin: {pin}")
        return None
    except Exception as e:
        logging.error(f"Error reading pin {pin}: {e}")
        return None

def trigger_door(relay, duration=0.5):
    """Triggers the door relay for a specified duration."""
    try:
        logging.info("Triggering door relay...")
        automationhat.relay[relay].on()
        time.sleep(duration)
        automationhat.relay[relay].off()
        logging.info("Door relay deactivated.")
    except IndexError:
        logging.error(f"Invalid relay pin: {relay}")
        return False
    except Exception as e:
        logging.error(f"Error triggering relay {relay}: {e}")
        return False
    return True

class GarageDoor:
    """Represents a garage door controlled by an Automation HAT."""

    def __init__(self, state_pin):
        """Initializes the GarageDoor object."""
        if not hasattr(self, 'state_pin'):
            raise AttributeError("state_pin must be initialized in the initialize method")
        self.state_pin = self.state_pin

    @property
    def state(self):
        """Returns the current state of the door (open or closed)."""
        return DOOR_OPEN if read_state(self.state_pin) is None else DOOR_CLOSED

    @state.setter
    def state(self, value):
        """Sets the state of the door and triggers the corresponding action."""
        if value not in (DOOR_CLOSED, DOOR_OPEN):
            raise ValueError("Invalid state value. Must be 'closed' or 'open'.")


    def trigger(self):
        """Triggers the door relay to open or close the door."""
        if self.state == DOOR_CLOSED:
            trigger_door(self.state_pin)
        else:
            trigger_door(self.state_pin, duration=0.5)  # Open the door


def main():
    """Main function to control the garage door."""

    try:
        garage = initialize_garage_door(1) # Example using state_pin 1
        if garage is None:
            return

        # Create partial functions for reading and triggering the door
        read_current_state = partial(read_state, garage.state_pin)
        trigger_door_object = partial(trigger_door, garage.state_pin)

        # Example usage:
        garage.state = DOOR_CLOSED
        while garage.state == DOOR_CLOSED:
            print("Door is closed.")
            time.sleep(1)
            trigger_door_object()
            while garage.state == DOOR_OPEN:
                print("Door is open.")
                time.sleep(1)


    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.exception(f"An unexpected error occurred: {e}")
    finally:
        # Ensure relay is off on exit
        try:
            automationhat.relay[1].off() # Assuming relay is on pin 1
        except IndexError:
            pass
        except Exception as e:
            logging.error(f"Error turning off relay on exit: {e}")



if __name__ == "__main__":
    main()

