import logging
import signal
import sys
from smbus2 import SMBus, i2c_msg

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
SERVO_MIN_PULSE = 150
SERVO_MAX_PULSE = 600
SERVO_CENTER_PULSE = (SERVO_MAX_PULSE + SERVO_MIN_PULSE) // 2
DEFAULT_SERVO_FREQUENCY = 60  # Hz
DEFAULT_SERVO_CHANNEL = 0
I2C_BUS_NUMBER = 1
PCA9685_ADDRESS = 0x40
PCA9685_MODE1 = 0x00
PCA9685_PRESCALE = 0xFE
SERVO_ANGLE_MIN = -77
SERVO_ANGLE_MAX = 77
SERVO_ANGLE_STEP = 10
SERVO_DELAY = 0.25  # seconds

class ServoError(Exception):
    """Custom exception for servo-related errors."""
    pass

class PCA9685:
    """Driver for the PCA9685 PWM controller."""

    def __init__(self, bus_number=I2C_BUS_NUMBER, address=PCA9685_ADDRESS, frequency=DEFAULT_SERVO_FREQUENCY, debug=False):
        """Initializes the PCA9685 driver."""
        self.bus_number = bus_number
        self.address = address
        self.frequency = frequency
        self.debug = debug
        self.bus = None
        self._initialize()


    def _initialize(self):
        """Performs initial communication and hardware check."""
        try:
            self.bus = SMBus(self.bus_number)
            if self.debug:
                logger.info(f"Opened I2C bus {self.bus_number}")

            # Verify PCA9685 presence by reading the MODE1 register
            try:
                who_am_i = self.read_byte(PCA9685_MODE1)
                if who_am_i != 0x18:
                    raise ServoError(f"PCA9685 not found at address 0x{self.address:02X}. Who am I? 0x{who_am_i:02X}")
                logger.info("PCA9685 found successfully.")
            except Exception as e:
                raise ServoError(f"Error communicating with PCA9685: {e}")

        except Exception as e:
            raise ServoError(f"Failed to initialize PCA9685: {e}")


    def _send_pwm_command(self, register, message):
        """Sends a PWM command to the PCA9685."""
        try:
            with i2c_msg.Outlander(self.address, self.bus_number) as msg:
                msg.write8(register, message)
        except Exception as e:
            raise ServoError(f"Error sending PWM command: {e}")


    def _calculate_pulse(self, angle):
        """Calculates the PWM pulse length for a given angle."""
        zero_pulse = SERVO_CENTER_PULSE - SERVO_MIN_PULSE
        pulse_range = zero_pulse * 2
        pulse = zero_pulse + (pulse_range * angle / SERVO_ANGLE_MAX)
        return int(pulse)


    def set_servo_angle(self, channel, angle):
        """Sets the angle of a servo connected to the PCA9685."""
        if not 0 <= channel <= 15:
            raise ValueError("Channel must be between 0 and 15")

        if not SERVO_ANGLE_MIN <= angle <= SERVO_ANGLE_MAX:
            raise ValueError(f"Angle must be between {SERVO_ANGLE_MIN} and {SERVO_ANGLE_MAX}")

        try:
            pulse = self._calculate_pulse(angle)
            self._send_pwm_command(PCA9685_MODE1 + channel, pulse)
            if self.debug:
                logger.info(f"Servo channel {channel} set to {angle} (pulse {pulse})")
            time.sleep(SERVO_DELAY)
        except ServoError as e:
            logger.error(f"Failed to set servo angle: {e}")
            # Implement recovery logic here if needed


    def cleanup(self):
        """Releases I2C resources."""
        if self.bus:
            try:
                self.bus.close()
                logger.info("I2C bus closed.")
            except Exception as e:
                logger.error(f"Error closing I2C bus: {e}")


def signal_handler(sig, frame):
    """Handles SIGINT signal for graceful shutdown."""
    logger.info("Shutting down gracefully...")
    servo_controller.cleanup()
    sys.exit(0)


if __name__ == "__main__":
    servo_controller = None
    try:
        servo_controller = PCA9685(debug=True)
        signal.signal(signal.SIGINT, signal_handler)

        # Test servo movement sequence
        try:
            for angle in [-77, -66, -55, -44, -33, -22, -11, 0, 11, 22, 33, 44, 55, 66, 77]:
                servo_controller.set_servo_angle(DEFAULT_SERVO_CHANNEL, angle)
            logger.info("Servo test sequence completed successfully.")
        except ServoError as e:
            logger.error(f"Servo error during test: {e}")

    except Exception as e:
        logger.exception(f"An unexpected error occurred: {e}")
    finally:
        if servo_controller:
            servo_controller.cleanup()

