            return True
        else:
            logger.error(f"Error connecting to AWS IoT Core: {response}")
            return False
    except Exception as e:
        logger.error(f"Error connecting to AWS IoT Core: {e}")
        return False



def receive_message(client: boto3.client, topic: str) -> Tuple[bool, str]:
    """Listens for messages on a specified AWS IoT Core topic."""
    try:
        response = client.subscribe(topic=topic, client_id="RaspberryPi_Client")
        logger.info(f"Subscribed to topic: {topic}")

        while True:
            response = client.receive_message(topic=topic, client_id="RaspberryPi_Client", timeout=10)
            if response['message'] != None :
                message = json.loads(response['message'])
                logger.info(f"Received message: {message}")
                return True, message
            else:
                logger.debug("No message received, retrying...")
                time.sleep(1) # Avoid busy-waiting
    except Exception as e:
        logger.error(f"Error subscribing or receiving message: {e}")
        return False, None



def publish_message(client: boto3.client, topic: str, payload: str) -> bool:
    """Publishes a message to a specified AWS IoT Core topic."""
    try:
