            if not publish_message(client, "current sensor data", sensor_data):
                logger.warning("Failed to publish sensor data from local sensor.")
            else:
                logger.info("Published sensor data from local sensor to AWS IoT Core.")
        else:
            logger.warning("Invalid sensor data from local sensor.  Not publishing.")
    except Exception as e:
        logger.error(f"Error publishing sensor data from local sensor: {e}")


    # Example: Trigger the buzzer on a specific condition (e.g., error count exceeding threshold)
    error_count = 0
    max_errors = 3
    try:
        while True:
            if receive_message(client, FACE_REKO_TOPIC):
                message = receive_message(client, FACE_REKO_TOPIC)[1]
                try:
                    data = json.loads(message)
                    if "error" in data:
                        error_count += 1
                        if error_count > max_errors:
                            logger.error(f"Error count exceeded threshold: {error_count}. Triggering buzzer.")
                            trigger_buzzer(BUZZER)
