#!/usr/bin/python3

import smbus2 as smbus
import contextlib

class I2CDevice:
    """
    A robust and efficient I2C device interface for Raspberry Pi.

    Provides basic I2C communication functionalities with error handling and resource management.
    """

    def __init__(self, address, bus_number=1, debug=False):
        """
        Initializes the I2C device.

        Args:
            address (int): The I2C address of the device.
            bus_number (int, optional): The I2C bus number (default: 1).
            debug (bool, optional): Enable debug logging (default: False).
        """
        self.address = address
        self.bus_number = bus_number
        self.debug = debug
        self.bus = None

    def open(self):
        """
        Opens the I2C bus and verifies device communication.

        Raises:
            RuntimeError: If the device is not present or a communication error occurs.
        """
        try:
            self.bus = smbus.SMBus(self.bus_number)
            # Simple check to see if the device responds to a read byte
            try:
                self.bus.read_byte(self.address)
            except OSError as e:
                raise RuntimeError(f"I2C device at address {self.address} not found or communication failed: {e}")
        except Exception as e:
            raise RuntimeError(f"Error opening I2C bus: {e}")

    def close(self):
        """
        Closes the I2C bus.
        """
        if self.bus:
            try:
                self.bus.close()
                self.bus = None
            except Exception as e:
                print(f"Error closing I2C bus: {e}")

    def _write(self, register, value):
        """
        Writes a byte to the specified register.

        Args:
            register (int): The register address to write to.
            value (int): The byte value to write.

        Raises:
            IOError: If there's an error writing to the I2C device.
        """
        if self.bus is None:
            raise IOError("I2C bus not open")
        try:
            self.bus.write_byte_data(self.address, register, value)
        except OSError as e:
            raise IOError(f"Error writing to I2C device at address {self.address}, register {register}: {e}")

    def _read(self, register):
        """
        Reads a byte from the specified register.

        Args:
            register (int): The register address to read from.

        Returns:
            int: The byte value read from the register.

        Raises:
            IOError: If there's an error reading from the I2C device.
        """
        if self.bus is None:
            raise IOError("I2C bus not open")
        try:
            return self.bus.read_byte_data(self.address, register)
        except OSError as e:
            raise IOError(f"Error reading from I2C device at address {self.address}, register {register}: {e}")


    def write_byte(self, register, value):
        """Convenience wrapper for _write."""
        self._write(register, value)

    def read_byte(self, register):
        """Convenience wrapper for _read."""
        return self._read(register)

    def read_block(self, register, num_bytes):
        """Reads a block of bytes from the I2C device."""
        if self.bus is None:
            raise IOError("I2C bus not open")
        try:
            return self.bus.read_i2c_block_data(self.address, register, num_bytes)
        except OSError as e:
            raise IOError(f"Error reading block from I2C device at address {self.address}, register {register}, {num_bytes} bytes: {e}")


    def __enter__(self):
        """
        Context manager entry point.
        """
        self.open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """
        Context manager exit point.  Closes the I2C bus.
        """
        self.close()


if __name__ == "__main__":
    try:
        device = I2CDevice(address=0x40, bus_number=1, debug=True)  # Example address, bus 1
        # Perform I2C operations using the provided interfaces (e.g., write_byte, read_byte, read_block)
        device.write_byte(0x00, 0x55)
        value = device.read_byte(0x00)
        print(f"Read value: {value}")

    except RuntimeError as e:
        print(f"Error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

