REG_SECONDS = 0x00
REG_MINUTES = 0x01
REG_HOURS = 0x02
REG_DAY = 0x03
REG_DATE = 0x04
REG_MONTH = 0x05
REG_YEAR = 0x06
REG_CONTROL = 0x07

# Control register bits
CH_BIT = 0x01  # Clock halt bit
CE_BIT = 0x00  # Clock enable bit

# Value for 24-hour mode
TWELVE_HOUR_MODE = 0x00

def _bcd_to_int(bcd_value):
    """Converts a BCD value to an integer."""
    try:
        return (bcd_value >> 4) * 10 + (bcd_value & 0x0F)
    except TypeError:
        raise ValueError("Invalid BCD value")

def _int_to_bcd(int_value):
    """Converts an integer to BCD format."""
    if not 0 <= int_value <= 99:
        raise ValueError("Integer value must be between 0 and 99")
    return (int_value // 10 << 4) | (int_value % 10)

@contextmanager
def i2c_device(device_address, bus_number=1):
    """Context manager for I2C device."""
    try:
        bus = smbus2.SMBus(bus_number)
        yield bus, device_address
    finally:
        bus.close()

def _write_register(bus, device_address, register_address, data):
    """Writes data to a register."""
    try:
        bus.write_byte_data(device_address, register_address, data)
    except IOError as e:
        raise IOError(f"I2C write error: {e}")

def _read_register(bus, device_address, register_address):
    """Reads data from a register."""
    try:
