    except IOError as e:
        raise IOError(f"I2C read error: {e}")


def _read_all_registers(bus, device_address):
    """Reads all registers from the RTC."""
    data = []
    for register in (REG_SECONDS, REG_MINUTES, REG_HOURS, REG_DAY, REG_DATE, REG_MONTH, REG_YEAR):
        data.append(_read_register(bus, device_address, register))
    return data


def _write_all_registers(bus, device_address, data):
    """Writes all registers to the RTC."""
    for i, register in enumerate((REG_SECONDS, REG_MINUTES, REG_HOURS, REG_DAY, REG_DATE, REG_MONTH, REG_YEAR)):
        _write_register(bus, device_address, register, data[i])


def ds1338_read_all(bus, device_address):
    """Reads all time components from the RTC."""
    try:
        data = _read_all_registers(bus, device_address)
        return (_bcd_to_int(data[0]), _bcd_to_int(data[1]), _bcd_to_int(data[2]),
