    except Exception as e:
        raise IOError(f"Error reading RTC data: {e}")


def ds1338_read_datetime(bus, device_address):
    """Reads the current date and time and returns a datetime object."""
    try:
        year, month, day, hours, minutes, seconds = ds1338_read_all(bus, device_address)
        return datetime(year, month, day, hours, minutes, seconds)
    except Exception as e:
        raise IOError(f"Error converting RTC data to datetime: {e}")



def ds1338_write_all(bus, device_address, year, month, day, hours, minutes, seconds):
    """Writes the given date and time to the RTC."""

    if not 0 <= seconds <= 59:
        raise ValueError("Seconds must be between 0 and 59")
    if not 0 <= minutes <= 59:
        raise ValueError("Minutes must be between 0 and 59")
    if not 0 <= hours <= 23:
        raise ValueError("Hours must be between 0 and 23")
    if not 1 <= day <= 7:
        raise ValueError("Day must be between 1 and 7")
    if not 1 <= month <= 12:
        raise ValueError("Month must be between 1 and 12")
    if not 2000 <= year <= 2099:
        raise ValueError("Year must be between 2000 and 2099")

    try:
        _write_all_registers(bus, device_address, (_bcd_to_int(seconds), _bcd_to_int(minutes),
                                               _bcd_to_int(hours), _bcd_to_int(day),
                                               _bcd_to_int(month), _bcd_to_int(year), 0x6F))
    except Exception as e:
        raise IOError(f"Error writing to RTC: {e}")


def ds1338_write_datetime(bus, device_address, dt):
    """Writes the given datetime object to the RTC."""
    ds1338_write_all(bus, device_address, dt.year, dt.month, dt.day,
                      dt.hour, dt.minute, dt.second)


def ds1338_write_now(bus, device_address):
    """Writes the current time to the RTC."""
    try:
        now = datetime.now(datetime.timezone.utc)
        ds1338_write_datetime(bus, device_address, now)
    except Exception as e:
        raise IOError(f"Error writing current time: {e}")


