        """Reads all time components from the RTC."""
        return ds1338_read_all(self.bus, self.address)

    def read_datetime(self):
        """Reads the current date and time."""
        return ds1338_read_datetime(self.bus, self.address)

    def write_all(self, year, month, day, hours, minutes, seconds):
        """Writes the given date and time to the RTC."""
        ds1338_write_all(self.bus, self.address, year, month, day, hours, minutes, seconds)

    def write_datetime(self, dt):
        """Writes the given datetime object to the RTC."""
        ds1338_write_datetime(self.bus, self.address, dt)

    def write_now(self):
        """Writes the current time to the RTC."""
        ds1338_write_now(self.bus, self.address)


if __name__ == "__main__":
    rtc = DS1338(bus_num=1)
    try:
        current_time = rtc.read_datetime()
        print("Current time:", current_time)
    except IOError as e:
        print(f"Error communicating with RTC: {e}")
    finally:
        rtc.close()

