import serial
import time
import pynmea2
import os

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Log file path
LOG_FILE = 'gps_coordinates_log.txt'


def initialize_serial(port, baudrate, timeout):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None


def parse_gps_data(serial_connection):
    """Reads and parses NMEA data from the serial port."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line.startswith('$GPGGA'):
            msg = pynmea2.parse(line)
            return msg.latitude, msg.longitude, msg.altitude
        return None, None, None
    except pynmea2.ParseError as e:
        print(f"NMEA Parse Error: {e}")
        return None, None, None
    except UnicodeDecodeError as e:
        print(f"Unicode Decode Error: {e}")
        return None, None, None


def log_coordinates(latitude, longitude, altitude, log_file):
    """Logs the GPS coordinates to a file."""
    if latitude is not None and longitude is not None and altitude is not None:
        timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
        log_entry = f'{timestamp} - Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude} m\n'
        try:
            with open(log_file, 'a') as file:
                file.write(log_entry)
        except IOError as e:
            print(f"Error writing to log file: {e}")


def main():
    """Main function to read and log GPS data."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.")
        return

    try:
        while True:
            latitude, longitude, altitude = parse_gps_data(serial_connection)

            if latitude is not None and longitude is not None and altitude is not None:
                print(f'Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude} m')
                log_coordinates(latitude, longitude, altitude, LOG_FILE)

            time.sleep(1)

    except KeyboardInterrupt:
        print("Program terminated by user.")

    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

