import serial
import time
import signal
import sys

class GPS:
    def __init__(self, port='/dev/ttyAMA0', baud=9600):
        """Initializes the GPS object.

        Args:
            port (str): Serial port (default: '/dev/ttyAMA0').
            baud (int): Baud rate (default: 9600).
        """
        self.port = port
        self.baud = baud
        self.ser = None  # Initialize serial port to None
        self.running = False

    def open(self):
        """Opens the serial port."""
        try:
            self.ser = serial.Serial(self.port, self.baud, timeout=1)  # Add timeout for safer reads
            self.running = True
            return True
        except serial.SerialException as e:
            print(f"Error opening serial port: {e}")
            return False

    def close(self):
        """Closes the serial port."""
        if self.ser and self.ser.is_open:
            self.ser.close()
            self.running = False
            print("Serial port closed.")

    def attach(self):
        """Attaches to the GPS module and powers on the GNSS."""
        if not self.running:
            if not self.open():
                return False

        if not self.ser.is_open:
            print("Serial port not open, cannot attach.")
            return False

        try:
            self.ser.write(b'AT+CGNSPWR=1\r\n')  # Power on GNSS
            time.sleep(1)  # Wait for it to power on
            # Check if the command was successful
            if self._read_response(b'OK\r\n'):
                print("GPS attached, powered on.")
                return True
            else:
                print("Error powering on GPS.")
                return False
        except serial.SerialException as e:
            print(f"Serial communication error: {e}")
            return False

    def detach(self):
        """Detaches from the GPS module and powers off the GNSS."""
        if not self.running:
            print("Not attached to GPS.")
            return False

        if not self.ser.is_open:
            print("Serial port not open, cannot detach.")
            return False

        try:
            self.ser.write(b'AT+CGNSPWR=0\r\n')  # Power off GNSS
            if self._read_response(b'OK\r\n'):
                print("GPS detached, powered off.")
                return True
            else:
                print("Error powering off GPS.")
                return False
        except serial.SerialException as e:
            print(f"Serial communication error: {e}")
            return False

    def get_data(self):
        """Reads and parses GPS data. Returns a tuple (latitude, longitude, altitude) or None on error."""
        if not self.running:
            print("Not attached to GPS.")
            return None

        if not self.ser.is_open:
            print("Serial port not open, cannot read data.")
            return None

        try:
            if self.ser.in_waiting:
                line = self.ser.readline().decode('utf-8', errors='ignore').strip()
                if line.startswith('$GPRMC'):
                    parts = line.split(',')
                    if parts[2] == 'A':  # Check if the data is valid
                        latitude = parts[3]
                        longitude = parts[5]
                        altitude = parts[9] if len(parts) > 8 else None
                        return latitude, longitude, altitude
                    else:
                        print("Invalid GPS data received.")
                        return None
                elif parts[0] == '$GPGGA':  # Check for complete GPGGA messages
                    latitude = parts[2]
                    longitude = parts[4]
                    altitude = parts[9] if len(parts) > 9 else None
                    return latitude, longitude, altitude
                else:
                    return None  # Handle other messages
            else:
                return None  # No data available

        except serial.SerialException as e:
            print(f"Serial communication error: {e}")
            return None
        except Exception as e:
            print(f"Error processing GPS data: {e}")
            return None

    def _read_response(self, expected):
        """Reads data until the expected string is received."""
        while True:
            if self.ser and self.ser.in_waiting:
                line = self.ser.readline().decode('utf-8', errors='ignore').strip()
                if line == expected:
                    return True
                elif line == b'':  # Handle end of transmission
                    return False
            else:
                return False  # No serial data available


def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    print("Exiting gracefully...")
