    """Manages the serial connection, handling errors and closing."""
    with SERIAL_EXCEPTION_LOCK:
        try:
            serial_port = Serial(port, baudrate, timeout=SERIAL_TIMEOUT)
            if not serial_port.is_open:
                raise SerialException(f"Could not open serial port {port}")
            return serial_port
        except SerialException as e:
            with SERIAL_EXCEPTION_LOCK:
                print(f"Serial error: {e}")
                raise  # Re-raise for handling in calling function
        except Exception as e:
            with SERIAL_EXCEPTION_LOCK:
                print(f"Unexpected serial error: {e}")
                raise


def safe_serial_send(serial_port: Serial, command: str) -> None:
    """Sends a command to the serial port, handling potential errors."""
    with SERIAL_EXCEPTION_LOCK:
        try:
            serial_port.write(command.encode() + b"\n")
        except SerialException as e:
            with SERIAL_EXCEPTION_LOCK:
                print(f"Serial send error: {e}")


def safe_serial_receive(serial_port: Serial) -> Optional[str]:
    """Receives data from the serial port, handling potential errors."""
    with SERIAL_EXCEPTION_LOCK:
        try:
            response = serial_port.readline().decode().strip()  # Read a single line
            return response
        except SerialException as e:
            with SERIAL_EXCEPTION_LOCK:
                print(f"Serial receive error: {e}")
                return None
        except Exception as e:
            with SERIAL_EXCEPTION_LOCK:
                print(f"Unexpected serial receive error: {e}")
                return None


def read_serial_line(serial_port: Serial, timeout: int = SERIAL_TIMEOUT) -> Optional[str]:
    """Reads a line from the serial port within a timeout."""
    start_time = time.time()
    while time.time() - start_time < timeout:
        if serial_port.in_waiting:
            line = serial_port.readline().decode().strip()
            if line:
                return line
    return None


