        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()

    def open(self) -> None:
        """Opens the serial port."""
        with SERIAL_EXCEPTION_LOCK:
            if self.serial_port and self.serial_port.is_open:
                return  # Already open
            try:
                self.serial_port = serial_communicator(self.port, self.baudrate)
                if not self.serial_port.is_open:
                    raise SerialException("Serial port opened but could not be opened")
                print(f"Opened serial port {self.port} at {self.baudrate} baud")
            except SerialException as e:
                raise  # Re-raise

    def close(self) -> None:
        """Closes the serial port."""
        with SERIAL_EXCEPTION_LOCK:
            if self.serial_port and self.serial_port.is_open:
                try:
                    self.serial_port.close()
                    print(f"Closed serial port {self.port}")
                except SerialException as e:
                    print(f"Error closing serial port: {e}")
                finally:
                    self.serial_port = None


