def check_timeout() -> None:
    """Checks for timeout exceptions in serial_communicator."""
    while True:
        time.sleep(1)
        with SERIAL_EXCEPTION_LOCK:
            if hasattr(serial_communicator, 'serial_port') and serial_communicator.serial_port and serial_communicator.serial_port.is_open:
                if isinstance(serial_communicator.serial_port, Serial) and hasattr(serial_communicator.serial_port, 'in_waiting'):
                    pass  # Normal operation
                else:
                    print("Timeout: Serial port unexpectedly closed.")
                    raise RuntimeError("Serial port unexpectedly closed")


def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    print("Shutting down gracefully...")
    global app
    app.stop()
    sys.exit(0)


def main() -> None:
    """Initializes and runs the web interface and serial communication."""
    global app

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    manager = DataManager()
    communicator = Communicator(serial_port)

    # Start the serial communication thread
    serial_thread = Thread(target=read_thread, args=(serial_port,), daemon=True)
    serial_thread.start()

    # Start the control thread
    control_thread_func = control_thread(communicator)
    control_thread_instance = control_thread_func(serial_port)
    control_thread_instance.daemon = True
    control_thread_instance.start()

    # Start the timeout check thread
    timeout_thread = Thread(target=check_timeout, daemon=True)
    timeout_thread.start()

    app.run(debug=False, host='0.0.0.0')


if __name__ == '__main__':
    serial_port = Serial(SERIAL_PORT, BAUDRATE, timeout=SERIAL_TIMEOUT)
    if not serial_port.is_open:
        raise SerialException(f"Could not open serial port {SERIAL_PORT}")
    main()

