from threading import Thread
from flask import Flask, render_template, request, jsonify, abort
import serial
import json

app = Flask(__name__)
store = [{'id': 1, 'name': 'CHIPS', 'done': False}, {'id': 2, 'name': 'garden', 'done': False}]
ser = None

def open_serial():
    global ser
    try:
        ser = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)
        return True
    except serial.SerialException as e:
        print(f"Serial port error: {e}")
        return False

def get_instrument_info():
    if not ser:
        return jsonify({'error': 'Serial port not open'}), 503
    try:
        ser.write(b'*IDN?\n')
        time.sleep(0.1)
        r = ser.read_all().decode('utf-8', errors='ignore').split('\n')
        return jsonify(r), 200
    except Exception as e:
        print(f"Serial communication error: {e}")
        return jsonify({'error': str(e)}), 500

@app.route('/version', methods=['GET'])
def version():
    return get_instrument_info()

@app.route('/getdata', methods=['GET'])
def get_data():
    return jsonify(store), 200

@app.route('/getset/<int:item_id>', methods=['GET'])
def get_item(item_id):
    item = next((item for item in store if item['id'] == item_id), None)
    if item:
        return jsonify(item), 200
    else:
        abort(404)

@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def post_item(item_id, name):
    item = next((item for item in store if item['id'] == item_id), None)
    if item:
        item['name'] = name
        return jsonify(item), 200
    else:
        abort(404)

@app.route('/postjson', methods=['POST', 'GET'])
def post_json():
    if request.method == 'POST':
        try:
            data = request.get_json()
        except (KeyError, TypeError):
            data = request.form
    else:
        data = request.get_json() or request.form

    if not data:
        return jsonify({'error': 'No data provided'}), 400

    new_item = {
        'id': store[-1]['id'] + 1 if store else 1,
        'name': data.get('name', ''),
        'done': data.get('done', '').lower() in ('true', '1', 'yes')
    }

    store.append(new_item)
    return jsonify(store), 201

